            except Exception:
                w("PRINT_TEST_FAIL: %s" % traceback.format_exc())
            w("GAME_LOOP_TEST_PASS: %d frames in %.1fs" % (state["frames"], el))
            unreal.SystemLibrary.execute_console_command(world, "quit")
            w("QUIT issued")

    try:
        handle = unreal.register_slate_post_tick_callback(game_tick)
        w("SLATE_TICK_ARMED handle=%s" % handle)
    except Exception:
        w("SLATE_TICK_FAIL: %s" % traceback.format_exc())

