w("=== PROBE V18 (Key + pawn) ===")

world = None
pc = None
pawn = None
try:
    n = 0
    for o in unreal.ObjectIterator():
        n += 1
        if n > 300000:
            break
        try:
            cls = o.get_class()
            if cls is None or cls.get_name() != "World":
                continue
            try:
                pc = unreal.GameplayStatics.get_player_controller(o, 0)
                if pc is not None:
                    world = o
                    pawn = unreal.GameplayStatics.get_player_pawn(o, 0)
                    break
            except Exception:
