            w("pawn caps: %s" % [a for a in dir(pawn) if any(s in a.lower() for s in ("velocity", "jump", "movement"))][:10])
        except Exception:
            pass

    # input poll in tick
    state = {"frames": 0, "t0": time.time(), "done": False}

    def game_tick(dt):
        state["frames"] += 1
        el = time.time() - state["t0"]
        if not state["done"] and el >= 3.0:
            state["done"] = True
            if key_ok:
                try:
                    k = unreal.Key()
                    k.set_editor_property(key_ok, unreal.Name("E"))
                    down = pc.is_input_key_down(k)
                    w("INPUT_POLL_PASS: E down=%s (nobody pressing)" % down)
                except Exception:
                    w("INPUT_POLL_FAIL: %s" % traceback.format_exc())
