                w("pawn loc after 3s: %s" % (p2.get_actor_location() if p2 else None))
            except Exception:
                pass
            w("PROBE18_DONE frames=%d" % state["frames"])
            unreal.SystemLibrary.execute_console_command(world, "quit")
