# ============================================================================
# THE KEEPER'S LEDGER — core game module
# Driven by slate post-tick (game thread). See init_unreal.py bootstrap.
# Design: SPEC_LOCK.md v1.0. The job is the story; the record decides the end.
# ============================================================================
import unreal, os, json, math, random, time, traceback

ROOT = os.path.abspath(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..", "..", ".."))
LOG_DIR = os.path.join(ROOT, "logs")
os.makedirs(LOG_DIR, exist_ok=True)
GAME_LOG = os.path.join(LOG_DIR, "game.log")
SAVE_DIR = os.path.join(ROOT, "game", "ScalTest", "Saved", "KeeperSaves")
os.makedirs(SAVE_DIR, exist_ok=True)
SAVE_PATH = os.path.join(SAVE_DIR, "slot0.json")

def glog(m):
    try:
        with open(GAME_LOG, "a") as f:
            f.write(m + "\n")
    except Exception:
        pass

# ---------------------------------------------------------------- config ---
CFG = {
    "day_seconds": 45.0,
    "night_seconds": 40.0,
    "cycles": 7,
    "oil_start": 60.0,
    "lens_decay_per_night": 10.0,
    "salvage_oil": 6.0,
    "wreck_to_reef_cycles": 2,
    "ship_speed": 150.0,
    "beam_half_angle_deg": 30.0,
    "beam_range_base": 1500.0,   # uu at lens 0
    "beam_range_per_lens": 60.0, # uu per lens point (max +6000)
    "fog_fury_threshold": 0.7,
    "fog_range_factor": 0.65,
    "ship_sink_open_sea": 0.0,   # deterministic: no beam at decision = lost
}
# dev harness: fast timings if config.json present next to this file
_cfg_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "config.json")
if os.path.exists(_cfg_path):
    try:
        with open(_cfg_path) as f:
            over = json.load(f)
        CFG.update(over)
        glog("config override: %s" % over)
    except Exception:
        pass

WRECK_SLOT_X = [-600, -360, -120, 120, 360, 600]
LANE_Y = 2200.0
LH_X, LH_Y = 300.0, 0.0

NOTES = {
    "Note_Lens": ("Keeper Maren's note, 3rd winter",
                  "The salt takes a tenth of the glass every night. "
                  "I stopped cleaning for two storms. The Merrow went dark-side of the shoal. "
                  "Clean the glass, or the fog eats your light."),
    "Note_Oil": ("Keeper Maren's ledger page, final entry",
                  "The boat stopped coming. Oil is only what the sea gives back. "
                  "I burned the reserve to keep the Merrow's lane lit and let the wreck rot on the sand. "
                  "It is a reef now. I have chosen wrong twice."),
    "Note_Report": ("Keeper Aldous's report, unsent",
                     "Maren vanished after the third dark night. The inspector reads what we write — "
                     "and what we fail to. Report every wreck. The island keeps its own ledger too."),
}

# ----------------------------------------------------------------- state ---
S = {
    "booted": False, "world": None, "pc": None,
    "actors": {},            # label -> actor
    "phase": "DAY", "phase_t": 0.0, "cycle": 1,
    "oil": CFG["oil_start"], "lens": 100.0,
    "lamp_lit": False, "lamp_dead_at": None,
    "storm": {"fury": 0.5, "wind": 0.0},
    "ships": [],             # active night ships
    "wrecks": {},            # slot_idx -> {"reported":bool,"age":cycles}
    "reefs": set(),          # slot_idx with active reef
    "record": [],            # keeper record events
    "notes_found": set(),
    "day_flags": {"lamp": False, "lens": False, "log": False},
    "dark_nights": 0, "consecutive_dark": 0,
    "hud_t": 0.0, "ended": False, "ending": None,
    "keys_prev": {}, "beam_yaw": 0.0,
    "saved_total": 0, "lost_total": 0,
}

def rec(cat, text):
    S["record"].append({"cycle": S["cycle"], "phase": S["phase"], "cat": cat, "text": text})
    glog("REC c%d %s: %s" % (S["cycle"], cat, text))

# ------------------------------------------------------------ actor cache ---
def find_actors():
    world = S["world"]
    want = ("Station_Lamp", "Station_Lens", "Station_Oil", "Station_Log",
            "BeamLight", "TowerGlow", "Sun", "SkyLight", "StormFog",
            "Note_Lens", "Note_Oil", "Note_Report", "Reef_0")
    found = {}
    try:
        smas = unreal.GameplayStatics.get_all_actors_of_class(world, unreal.StaticMeshActor)
        for a in smas:
            try:
                lbl = a.get_actor_label()
                if lbl in want or lbl.startswith("Ship_") or lbl.startswith("Wreck_"):
                    found[lbl] = a
            except Exception:
                continue
        lights = unreal.GameplayStatics.get_all_actors_of_class(world, unreal.LightActorBase)
        for a in lights:
            try:
                lbl = a.get_actor_label()
                if lbl in want:
                    found[lbl] = a
            except Exception:
                continue
        fog = unreal.GameplayStatics.get_all_actors_of_class(world, unreal.ExponentialHeightFog)
        for a in fog:
            found.setdefault("StormFog", a)
    except Exception:
        glog("find_actors fail: %s" % traceback.format_exc())
    S["actors"] = found
    glog("actors cached: %d (%s)" % (len(found), ", ".join(sorted(found))[:180]))

# --------------------------------------------------------------- helpers ---
def toast(pc, msg, seconds=4.0):
    try:
        unreal.SystemLibrary.print_string(pc, msg, True, True,
                                          unreal.LinearColor(r=1.0, g=0.85, b=0.4, a=1.0), seconds)
    except Exception:
        pass

def key_edge(name, down):
    prev = S["keys_prev"].get(name, False)
    S["keys_prev"][name] = down
    return down and not prev

def poll_key(pc, keyname):
    try:
        k = unreal.Key()
        k.set_editor_property("keyname", unreal.Name(keyname))
        return pc.is_input_key_down(k)
    except Exception:
        return False

def set_light(actor, intensity):
    try:
        comp = actor.get_component_by_class(unreal.LightComponent)
        if comp:
            comp.set_editor_property("intensity", intensity)
    except Exception:
        pass

def storm_roll():
    fury = random.uniform(0.25, 1.0)
    # gentle escalation with cycle number
    fury = min(1.0, fury + (S["cycle"] - 1) * 0.05)
    S["storm"] = {"fury": fury, "wind": random.uniform(0, 360)}
    glog("storm c%d fury=%.2f wind=%.0f" % (S["cycle"], fury, S["storm"]["wind"]))

def beam_range_uu():
    r = CFG["beam_range_base"] + S["lens"] * CFG["beam_range_per_lens"]
    if S["storm"]["fury"] > CFG["fog_fury_threshold"]:
        r *= CFG["fog_range_factor"]
    return r

# ------------------------------------------------------------ day/night ----
def start_day():
    S["phase"] = "DAY"
    S["phase_t"] = 0.0
    S["cycle"] += 1 if S["day_flags"] else 0  # no-op guard; cycle set at dawn()
    S["lamp_lit"] = False
    S["lamp_dead_at"] = None
    S["day_flags"] = {"lamp": False, "lens": False, "log": False}
    # hide ships
    for sh in S["ships"]:
        try:
            sh["actor"].set_actor_hidden_in_game(True)
        except Exception:
            pass
    S["ships"] = []
    # lens salt decay from last night
    S["lens"] = max(0.0, S["lens"] - CFG["lens_decay_per_night"])
    # day lighting
    try:
        set_light(S["actors"].get("Sun"), 3.0)
        set_light(S["actors"].get("SkyLight"), 1.0)
        set_light(S["actors"].get("BeamLight"), 0.0)
        fogc = S["actors"].get("StormFog")
        if fogc:
            comp = fogc.get_component_by_class(unreal.ExponentialHeightFogComponent)
            if comp:
                comp.set_editor_property("fog_density", 0.015)
    except Exception:
        pass
    # wrecks wash ashore: chance based on last night's losses + random
    washed = 0
    for i in range(len(WRECK_SLOT_X)):
        if i in S["wrecks"]:
            continue  # already ashore, unprocessed
        if random.random() < 0.30:
            S["wrecks"][i] = {"reported": False, "age": 0}
            washed += 1
    # age unprocessed wrecks; form reefs
    for i in list(S["wrecks"].keys()):
        if not S["wrecks"][i]["reported"]:
            S["wrecks"][i]["age"] += 1
            if S["wrecks"][i]["age"] >= CFG["wreck_to_reef_cycles"]:
                S["reefs"].add(i)
                rec("REEF_FORMED", "An unreported wreck became a reef in the shipping lane (slot %d)." % i)
                toast(S["pc"], "The island remembers: a reef forms where a wreck was left.", 5.0)
        else:
            del S["wrecks"][i]  # processed wrecks clear
    # show wrecks ashore
    for i in S["wrecks"]:
        actor = S["actors"].get("Wreck_%d" % i)
        if actor:
            actor.set_actor_hidden_in_game(False)
    # storm preview for tonight
    storm_roll()
    if washed:
        toast(S["pc"], "Dawn. %d wreck(s) washed ashore." % washed, 5.0)
    toast(S["pc"], "DAY %d — storm coming: fury %.0f%%" % (S["cycle"], S["storm"]["fury"] * 100), 6.0)
    save_game()

def start_night():
    S["phase"] = "NIGHT"
    S["phase_t"] = 0.0
    # dusk duties check -> record omissions
    if not S["day_flags"]["lamp"]:
        rec("LAMP_NOT_LIT", "Dusk: the lamp was not lit.")
    if not S["day_flags"]["lens"] and S["lens"] < 70:
        rec("LENS_UNCLEANED", "Dusk: the lens was salted (%d%%) and not cleaned." % int(S["lens"]))
    if not S["day_flags"]["log"]:
        rec("LOG_SKIPPED", "Dusk: no log entry written today.")
    # lamp burn
    cost = 8.0 + S["storm"]["fury"] * 12.0
    if S["day_flags"]["lamp"]:
        if S["oil"] >= cost:
            S["oil"] -= cost
            S["lamp_lit"] = True
            S["lamp_dead_at"] = None
            rec("LAMP_LIT", "Lamp lit for the night (oil -%.0f, %.0f left)." % (cost, S["oil"]))
        else:
            frac = S["oil"] / cost
            S["oil"] = 0.0
            S["lamp_lit"] = True
            S["lamp_dead_at"] = CFG["night_seconds"] * frac
            rec("LAMP_SHORT", "Lamp lit but oil ran short: light dies at %.0f%% of the night." % (frac * 100))
    else:
        S["lamp_lit"] = False
        S["lamp_dead_at"] = 0.0
    # night lighting
    try:
        set_light(S["actors"].get("Sun"), 0.12)
        set_light(S["actors"].get("SkyLight"), 0.06)
        fogc = S["actors"].get("StormFog")
        if fogc:
            comp = fogc.get_component_by_class(unreal.ExponentialHeightFogComponent)
            if comp:
                comp.set_editor_property("fog_density", 0.03 + S["storm"]["fury"] * 0.10)
    except Exception:
        pass
    # spawn ships
    n = 2 + int(S["storm"]["fury"] * 4)
    free = [a for a in range(8)]
    random.shuffle(free)
    S["ships"] = []
    for j in range(n):
        actor = S["actors"].get("Ship_%d" % free[j])
        if not actor:
            continue
        actor.set_actor_hidden_in_game(False)
        start_x = -2000.0 - j * 220.0
        actor.set_actor_location(unreal.Vector(start_x, LANE_Y + random.uniform(-120, 120), 40), False, True)
        S["ships"].append({"actor": actor, "x": start_x, "y": actor.get_actor_location().y,
                           "decided": False, "alive": True})
    glog("night c%d: %d ships, lamp=%s dead_at=%s" % (S["cycle"], len(S["ships"]), S["lamp_lit"], S["lamp_dead_at"]))
    toast(S["pc"], "NIGHT %d — %d ships in the dark. Fury %.0f%%" % (S["cycle"], len(S["ships"]), S["storm"]["fury"] * 100), 6.0)

def end_night():
    # night outcome
    dark = not S["lamp_lit"] or (S["lamp_dead_at"] is not None and S["lamp_dead_at"] <= 0.0)
    if not S["lamp_lit"] or S["oil"] <= 0.0 and S["lamp_dead_at"] is not None:
        pass
    if dark or S["lamp_dead_at"] == 0.0:
        S["dark_nights"] += 1
        S["consecutive_dark"] += 1
        rec("NIGHT_DARK", "Night %d passed in darkness." % S["cycle"])
    else:
        S["consecutive_dark"] = 0
    # dawn = day start of next cycle
    S["cycle"] += 1
    if S["cycle"] > CFG["cycles"]:
        finish()
        return
    start_day()

# ----------------------------------------------------------------- ships ---
def ship_tick(dt):
    if S["phase"] != "NIGHT":
        return
    # lamp death mid-night
    if S["lamp_lit"] and S["lamp_dead_at"] is not None and S["phase_t"] >= S["lamp_dead_at"]:
        S["lamp_lit"] = False
        rec("LIGHT_DIED", "The light died mid-night (oil exhausted).")
        toast(S["pc"], "The light dies...", 4.0)
    # beam
    beam_actor = S["actors"].get("BeamLight")
    if S["lamp_lit"]:
        S["beam_yaw"] = (S["beam_yaw"] + 90.0 * dt) % 360.0
        if beam_actor:
            beam_actor.set_actor_rotation(unreal.Rotator(0, S["beam_yaw"], 0), False)
        set_light(beam_actor, 8.0)
        set_light(S["actors"].get("TowerGlow"), 6.0)
    else:
        if beam_actor:
            set_light(beam_actor, 0.0)
        set_light(S["actors"].get("TowerGlow"), 0.5)
    # ships
    rng = beam_range_uu()
    for sh in S["ships"]:
        if not sh["alive"]:
            continue
        sh["x"] += CFG["ship_speed"] * dt
        try:
            sh["actor"].set_actor_location(unreal.Vector(sh["x"], sh["y"], 40), False, True)
        except Exception:
            pass
        # decision point: closest approach to lighthouse x
        if not sh["decided"] and sh["x"] >= LH_X - 60.0:
            sh["decided"] = True
            dx, dy = sh["x"] - LH_X, sh["y"] - LH_Y
            dist = math.sqrt(dx * dx + dy * dy)
            ang = math.degrees(math.atan2(dy, dx)) % 360.0
            diff = abs((ang - S["beam_yaw"] + 180.0) % 360.0 - 180.0)
            beam_ok = S["lamp_lit"] and diff <= CFG["beam_half_angle_deg"] and dist <= rng
            # reef in lane at this x?
            reef_hit = False
            for i in S["reefs"]:
                if abs(WRECK_SLOT_X[i] - sh["x"]) < 150.0:
                    reef_hit = True
                    break
            if beam_ok:
                S["saved_total"] += 1
                rec("SHIP_SAVED", "Ship saw the beam at %.0fm and stood off. (reef:%s)" % (dist / 100.0, reef_hit))
                toast(S["pc"], "A ship answers with two horns — it sees the light.", 4.0)
            elif reef_hit:
                sink(sh, "struck the reef in the dark")
            else:
                sink(sh, "found no light on the water")
        if sh["x"] > 2300.0:
            sh["alive"] = False
            try:
                sh["actor"].set_actor_hidden_in_game(True)
            except Exception:
                pass

def sink(sh, why):
    sh["alive"] = False
    S["lost_total"] += 1
    rec("SHIP_LOST", "A ship %s at x=%.0f." % (why, sh["x"]))
    toast(S["pc"], "A ship is lost on the rocks — %s." % why, 4.0)
    try:
        sh["actor"].set_actor_hidden_in_game(True)
    except Exception:
        pass
    # wreck ashore at nearest free slot
    slot = min(range(len(WRECK_SLOT_X)), key=lambda i: abs(WRECK_SLOT_X[i] - sh["x"]))
    if slot not in S["wrecks"]:
        S["wrecks"][slot] = {"reported": False, "age": 0}
        actor = S["actors"].get("Wreck_%d" % slot)
        if actor:
            actor.set_actor_hidden_in_game(False)

# ------------------------------------------------------------ interaction --
def nearest_interactable():
    pawn = None
    try:
        pawn = unreal.GameplayStatics.get_player_pawn(S["world"], 0)
    except Exception:
        return None, None
    if not pawn:
        return None, None
    ploc = pawn.get_actor_location()
    best, bdist = None, 1e9
    cands = {}
    for lbl in ("Station_Lamp", "Station_Lens", "Station_Oil", "Station_Log",
                "Note_Lens", "Note_Oil", "Note_Report"):
        a = S["actors"].get(lbl)
        if a:
            cands[lbl] = a
    for i in S["wrecks"]:
        a = S["actors"].get("Wreck_%d" % i)
        if a:
            cands["Wreck_%d" % i] = a
    for lbl, a in cands.items():
        try:
            d = a.get_distance_to(pawn)
            if d < bdist:
                best, bdist = lbl, d
        except Exception:
            continue
    if best and bdist < 220.0:
        return best, bdist
    return None, None

def interact(lbl):
    if lbl.startswith("Station_Lamp"):
        if S["day_flags"]["lamp"]:
            toast(S["pc"], "The lamp is already trimmed for tonight.")
        else:
            S["day_flags"]["lamp"] = True
            rec("LAMP_TRIMMED", "Lamp trimmed and ready for dusk.")
            toast(S["pc"], "Lamp trimmed. It will burn tonight if the oil holds.")
    elif lbl == "Station_Lens":
        S["lens"] = 100.0
        S["day_flags"]["lens"] = True
        rec("LENS_CLEANED", "Lens cleaned to 100%.")
        toast(S["pc"], "The glass gleams. Beam reach restored.")
    elif lbl == "Station_Oil":
        cost = 8.0 + S["storm"]["fury"] * 12.0
        toast(S["pc"], "Oil: %.0f  |  tonight's burn: %.0f  |  %s" %
              (S["oil"], cost, "ENOUGH" if S["oil"] >= cost else "NOT ENOUGH"), 6.0)
    elif lbl == "Station_Log":
        if S["day_flags"]["log"]:
            toast(S["pc"], "Today's page is already written.")
        else:
            S["day_flags"]["log"] = True
            rec("LOG_WRITTEN", "Log: day %d. Oil %.0f, lens %d%%, ships %d/%d." %
                (S["cycle"], S["oil"], int(S["lens"]), S["saved_total"], S["lost_total"]))
            toast(S["pc"], "Log written. The inspector will read it.")
    elif lbl.startswith("Note_"):
        if lbl in S["notes_found"]:
            toast(S["pc"], NOTES[lbl][0])
        else:
            S["notes_found"].add(lbl)
            title, body = NOTES[lbl]
            rec("NOTE_FOUND", title)
            toast(S["pc"], "%s — %s" % (title, body), 9.0)
    elif lbl.startswith("Wreck_"):
        idx = int(lbl.split("_")[1])
        wr = S["wrecks"].get(idx)
        if not wr:
            return
        # E = salvage, R = report (handled by caller)
        pass

def wreck_action(lbl, report):
    idx = int(lbl.split("_")[1])
    wr = S["wrecks"].get(idx)
    if not wr:
        return
    actor = S["actors"].get(lbl)
    if report:
        wr["reported"] = True
        rec("WRECK_REPORTED", "Wreck at slot %d reported to the ledger." % idx)
        toast(S["pc"], "Wreck reported. Its position is on the chart now.")
    else:
        S["oil"] += CFG["salvage_oil"]
        rec("WRECK_SALVAGED", "Wreck at slot %d salvaged for %.0f oil (unreported)." % (idx, CFG["salvage_oil"]))
        toast(S["pc"], "Salvaged %.0f oil. The wreck stays off the record." % CFG["salvage_oil"])
    S["wrecks"].pop(idx, None)
    if actor:
        actor.set_actor_hidden_in_game(True)

# ------------------------------------------------------------------ HUD ----
def hud_tick(dt):
    S["hud_t"] -= dt
    if S["hud_t"] > 0:
        return
    S["hud_t"] = 1.0
    try:
        t = S["phase_t"]
        remain = max(0.0, (CFG["day_seconds"] if S["phase"] == "DAY" else CFG["night_seconds"]) - t)
        lamp = "ON" if S["lamp_lit"] else "off"
        line1 = "CYCLE %d/%d  %s  %4.0fs | OIL %3.0f | LENS %3d%% | LAMP %s | SHIPS %d saved / %d lost" % (
            S["cycle"], CFG["cycles"], S["phase"], remain, S["oil"], int(S["lens"]), lamp,
            S["saved_total"], S["lost_total"])
        unreal.SystemLibrary.print_string(S["pc"], line1, True, False,
                                          unreal.LinearColor(r=0.8, g=0.95, b=1.0, a=1.0), 1.2)
        # interaction prompt
        lbl, d = nearest_interactable()
        if lbl:
            if lbl.startswith("Wreck_"):
                prompt = "[E] salvage +%.0f oil   [R] report wreck" % CFG["salvage_oil"]
            elif lbl.startswith("Note_"):
                prompt = "[E] read note"
            elif lbl == "Station_Oil":
                prompt = "[E] check oil"
            else:
                prompt = "[E] " + {"Station_Lamp": "trim the lamp",
                                   "Station_Lens": "clean the lens",
                                   "Station_Log": "write the log"}[lbl]
            unreal.SystemLibrary.print_string(S["pc"], prompt, True, False,
                                              unreal.LinearColor(r=1.0, g=0.85, b=0.4, a=1.0), 1.2)
    except Exception:
        pass

def record_dump():
    lines = ["=== KEEPER'S LEDGER — cycle %d ===" % S["cycle"]]
    for e in S["record"][-12:]:
        lines.append("c%d %s: %s" % (e["cycle"], e["cat"], e["text"]))
    try:
        unreal.SystemLibrary.print_string(S["pc"], "\n".join(lines), True, False,
                                          unreal.LinearColor(r=0.7, g=1.0, b=0.7, a=1.0), 3.0)
    except Exception:
        pass

# --------------------------------------------------------------- endings ---
def finish():
    S["ended"] = True
    saved, lost = S["saved_total"], S["lost_total"]
    logs = len([e for e in S["record"] if e["cat"] == "LOG_WRITTEN"])
    skips = len([e for e in S["record"] if e["cat"] == "LOG_SKIPPED"])
    notes = len(S["notes_found"])
    reported = len([e for e in S["record"] if e["cat"] == "WRECK_REPORTED"])
    salvaged = len([e for e in S["record"] if e["cat"] == "WRECK_SALVAGED"])
    score = saved * 3 - lost * 2 + logs - skips * 2 + notes * 2 + reported - S["dark_nights"] * 3
    if notes == 3 and lost == 0:
        ending = "THE FULL TRUTH — every ship lived, every page was found. The inspector closes the ledger in silence."
    elif score >= 25:
        ending = "KEEPER SUPREME — the light held, the record is clean, the sea owes you nothing."
    elif score >= 15:
        ending = "THE LIGHT HELD — storms took their due, but the inspector nods once."
    elif score >= 5:
        ending = "BARELY AFLOAT — the ledger has gaps. The inspector writes 'adequate' and leaves."
    else:
        ending = "THE DARK TAKES THE ISLAND — too many ships, too many blank pages. The light goes out."
    S["ending"] = {"score": score, "saved": saved, "lost": lost, "logs": logs,
                   "skips": skips, "notes": notes, "reported": reported,
                   "salvaged": salvaged, "dark_nights": S["dark_nights"], "text": ending}
    rec("INSPECTION", "Final score %d. %s" % (score, ending))
    try:
        with open(os.path.join(SAVE_DIR, "ending.json"), "w") as f:
            json.dump(S["ending"], f, indent=2)
    except Exception:
        pass
    toast(S["pc"], "=== INSPECTION ===", 30.0)
    toast(S["pc"], ending, 30.0)
    toast(S["pc"], "Score %d — saved %d, lost %d, notes %d/3, dark nights %d. ESC to exit." %
          (score, saved, lost, notes, S["dark_nights"]), 30.0)
    glog("ENDING: %s" % json.dumps(S["ending"]))
    save_game()

# ------------------------------------------------------------- save/load ---
def save_game():
    try:
        data = {"cycle": S["cycle"], "oil": S["oil"], "lens": S["lens"],
                "saved": S["saved_total"], "lost": S["lost_total"],
                "dark_nights": S["dark_nights"],
                "notes": sorted(S["notes_found"]),
                "wrecks": {str(k): v for k, v in S["wrecks"].items()},
                "reefs": sorted(S["reefs"]),
                "record": S["record"][-200:]}
        tmp = SAVE_PATH + ".tmp"
        with open(tmp, "w") as f:
            json.dump(data, f)
        os.replace(tmp, SAVE_PATH)
        glog("saved cycle %d" % S["cycle"])
    except Exception:
        glog("save fail: %s" % traceback.format_exc())

def load_game():
    try:
        with open(SAVE_PATH) as f:
            data = json.load(f)
        S["cycle"] = data.get("cycle", 1)
        S["oil"] = data.get("oil", CFG["oil_start"])
        S["lens"] = data.get("lens", 100.0)
        S["saved_total"] = data.get("saved", 0)
        S["lost_total"] = data.get("lost", 0)
        S["dark_nights"] = data.get("dark_nights", 0)
        S["notes_found"] = set(data.get("notes", []))
        S["wrecks"] = {int(k): v for k, v in data.get("wrecks", {}).items()}
        S["reefs"] = set(data.get("reefs", []))
        S["record"] = data.get("record", [])
        glog("loaded cycle %d" % S["cycle"])
        return True
    except Exception:
        return False

# ------------------------------------------------------------------ tick ---
def game_tick(dt):
    try:
        if not S["booted"]:
            return
        if S["ended"]:
            if poll_key(S["pc"], "Escape"):
                unreal.SystemLibrary.execute_console_command(S["world"], "quit")
            return
        S["phase_t"] += dt
        # keys
        e_down = poll_key(S["pc"], "E")
        r_down = poll_key(S["pc"], "R")
        tab_down = poll_key(S["pc"], "Tab")
        if key_edge("Tab", tab_down):
            record_dump()
        lbl, d = nearest_interactable()
        if lbl:
            if lbl.startswith("Wreck_"):
                if key_edge("E", e_down):
                    wreck_action(lbl, report=False)
                elif key_edge("R", r_down):
                    wreck_action(lbl, report=True)
            else:
                if key_edge("E", e_down):
                    interact(lbl)
        # phase progression
        limit = CFG["day_seconds"] if S["phase"] == "DAY" else CFG["night_seconds"]
        if S["phase"] == "NIGHT":
            ship_tick(dt)
        if S["phase_t"] >= limit:
            if S["phase"] == "DAY":
                start_night()
            else:
                end_night()
        # early ending: 2 consecutive dark nights
        if S["consecutive_dark"] >= 2 and not S["ended"]:
            S["record"].append({"cycle": S["cycle"], "phase": S["phase"], "cat": "ABANDON",
                                "text": "Two dark nights. The sea stops trusting the light."})
            finish()
            return
        hud_tick(dt)
    except Exception:
        glog("tick error: %s" % traceback.format_exc())

# ------------------------------------------------------------------ boot ---
def boot():
    glog("=== KEEPER'S LEDGER BOOT ===")
    # world discovery (guarded ObjectIterator — EditorLevelLibrary segfaults in -game)
    world = None
    try:
        n = 0
        for o in unreal.ObjectIterator():
            n += 1
            if n > 300000:
                break
            try:
                cls = o.get_class()
                if cls is None or cls.get_name() != "World":
                    continue
                try:
                    pc = unreal.GameplayStatics.get_player_controller(o, 0)
                    if pc is not None:
                        world = o
                        S["pc"] = pc
                        break
                except Exception:
                    continue
            except Exception:
                continue
    except Exception:
        glog("world scan fail: %s" % traceback.format_exc())
    if world is None:
        glog("BOOT FAIL: no world")
        return
    S["world"] = world
    glog("world: %s" % world.get_name())
    find_actors()
    load_game()
    S["cycle"] = max(1, S["cycle"])
    # fresh session starts at day 1 unless save had progress mid-run
    if S["cycle"] > CFG["cycles"]:
        S["cycle"] = 1
        S["record"] = []
        S["saved_total"] = S["lost_total"] = 0
        S["dark_nights"] = 0
        S["notes_found"] = set()
        S["wrecks"] = {}
        S["reefs"] = set()
    storm_roll()
    S["phase"] = "DAY"
    S["phase_t"] = 0.0
    S["booted"] = True
    toast(S["pc"], "THE KEEPER'S LEDGER — you are the last keeper. The boat is not coming.", 8.0)
    toast(S["pc"], "WASD move | E interact | R report wreck | Tab record | ESC quit", 8.0)
    glog("boot complete: cycle %d, oil %.0f" % (S["cycle"], S["oil"]))

