# ------------------------------------------------------- demo autoplayer ---
# Drives a full 7-cycle playthrough: trims lamp, cleans lens, writes log,
# salvages+reports wrecks, reads notes. Proves the whole loop end-to-end.
DEMO = {"on": False, "t": 0.0}

def demo_tick(dt):
    DEMO["t"] += dt
    if DEMO["t"] < 1.0:
        return
    DEMO["t"] = 0.0
    if S["ended"] or S["phase"] != "DAY":
        return
    pawn = None
    try:
        pawn = unreal.GameplayStatics.get_player_pawn(S["world"], 0)
    except Exception:
        return
    if not pawn:
        return
    # walk toward the next unmet duty
    targets = []
    if not S["day_flags"]["lamp"]:
        targets.append("Station_Lamp")
    if not S["day_flags"]["lens"]:
        targets.append("Station_Lens")
    if not S["day_flags"]["log"]:
        targets.append("Station_Log")
    for i in S["wrecks"]:
        targets.append("Wreck_%d" % i)
    for n in NOTES:
        if n not in S["notes_found"]:
            targets.append(n)
    if not targets:
        return
    # nearest target
    best, bdist = None, 1e9
    for lbl in targets:
        a = S["actors"].get(lbl)
        if not a:
            continue
        try:
            d = a.get_distance_to(pawn)
            if d < bdist:
                best, bdist = lbl, d
            elif d == bdist and lbl.startswith("Wreck_") and not best.startswith("Wreck_"):
                best = lbl
            elif d == bdist and lbl.startswith("Note_") and not (best.startswith("Wreck_") or best.startswith("Note_")):
                best = lbl
        except Exception:
            continue
    if not best:
        return
    # steer pawn toward it
    try:
        ploc = pawn.get_actor_location()
        aloc = S["actors"][best].get_actor_location()
        dx, dy = aloc.x - ploc.x, aloc.y - ploc.y
        dist = math.sqrt(dx * dx + dy * dy)
        if dist > 140.0:
            pawn.add_movement_input(unreal.Vector(dx / dist, dy / dist, 0), 1.0)
        else:
            if best.startswith("Wreck_"):
                wreck_action(best, report=True)  # demo reports (the honest keeper)
            elif best.startswith("Note_"):
                interact(best)
            else:
                interact(best)
    except Exception:
        pass

